      const translate = inject(TranslateService);
      const nzI18n = inject(NzI18nService);
      const saved = (() => {
        try {
          return localStorage.getItem("hre.lang");
        } catch {
          return null;
        }
      })();
      const lang = saved && /^(vi|en)$/.test(saved) ? saved : "vi";
      translate.addLangs(["vi", "en"]);
      translate.setDefaultLang("vi");
      const applyNzLocale = (l) => nzI18n.setLocale(l === "en" ? en_US : vi_VN);
